def subtract(a, b):
    # Merge overlapping/touching intervals and remove empty ones
    def merge(intervals):
        if not intervals:
            return []

        # Filter out empty intervals and sort
        valid = [iv for iv in intervals if iv[0] < iv[1]]
        if not valid:
            return []

        valid.sort()
        merged = [valid[0]]

        for start, end in valid[1:]:
            if start <= merged[-1][1]:
                # Overlapping or touching, merge
                merged[-1][1] = max(merged[-1][1], end)
            else:
                # Non-overlapping, add as new interval
                merged.append([start, end])

        return merged

    # Merge both a and b
    a_merged = merge(a)
    b_merged = merge(b)

    if not a_merged:
        return []

    if not b_merged:
        return a_merged

    # Subtract b from a
    result = []

    for a_start, a_end in a_merged:
        current = a_start

        for b_start, b_end in b_merged:
            if b_end <= current or b_start >= a_end:
                # No overlap
                continue

            # There is overlap
            if current < b_start:
                # Add the part before b
                result.append([current, b_start])

            # Move current past the b interval
            current = max(current, b_end)

        # Add any remaining part after all b intervals
        if current < a_end:
            result.append([current, a_end])

    return result

